    this.updateWorldTransform();
    this.previousWorldPosition.copy(this.worldPosition);
    this.previousWorldRotation.copy(this.worldRotation);
    this.previousWorldScale.copy(this.worldScale);

    // Prewarm feature
    if (this.config.prewarm) {
      this.prewarmSystem();
    }
