class PixelatedEdgePass {
	constructor(resolution) {
		this.resolution = resolution;

		const shader = {
			uniforms: {
				tDiffuse: { value: null },
				resolution: {
					value: new THREE.Vector4(
						resolution.x,
						resolution.y,
						1 / resolution.x,
						1 / resolution.y
					)
				},
				pixelSize: { value: 4.0 }
			},
			vertexShader: `
                varying vec2 vUv;
                
                void main() {
                    vUv = uv;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }
            `,
			fragmentShader: `
                uniform sampler2D tDiffuse;
                uniform vec4 resolution;
                uniform float pixelSize;
                varying vec2 vUv;

                vec2 pixelate(vec2 uv) {
                    vec2 pixels = resolution.xy / pixelSize;
                    return floor(uv * pixels) / pixels;
                }

                float luminance(vec3 color) {
                    return dot(color, vec3(0.299, 0.587, 0.114));
                }

                float edgeDetection(vec2 uv) {
                    vec2 texelSize = vec2(1.0 / resolution.x, 1.0 / resolution.y) * pixelSize;
                    
                    float center = luminance(texture2D(tDiffuse, uv).rgb);
                    float left = luminance(texture2D(tDiffuse, uv - vec2(texelSize.x, 0.0)).rgb);
                    float right = luminance(texture2D(tDiffuse, uv + vec2(texelSize.x, 0.0)).rgb);
                    float top = luminance(texture2D(tDiffuse, uv - vec2(0.0, texelSize.y)).rgb);
                    float bottom = luminance(texture2D(tDiffuse, uv + vec2(0.0, texelSize.y)).rgb);
                    
                    float sobelX = (-1.0 * left) + (1.0 * right);
                    float sobelY = (-1.0 * top) + (1.0 * bottom);
                    
                    return sqrt(sobelX * sobelX + sobelY * sobelY);
                }

                void main() {
                    vec2 pixelatedUV = pixelate(vUv);
                    vec4 texel = texture2D(tDiffuse, pixelatedUV);
                    
                    float edge = edgeDetection(pixelatedUV);
                    float edgeThreshold = 0.1;
                    float edgeStrength = 0.8;
                    
                    float coefficient = edge > edgeThreshold ? 
                        (1.0 - edgeStrength * edge) : 1.0;
                    
                    gl_FragColor = texel * coefficient;
                }
            `
		};

		this.material = new THREE.ShaderMaterial(shader);
		this.uniforms = this.material.uniforms;
		this.fsQuad = new THREE.FullScreenQuad(this.material);
		this.enabled = true;
		this.needsSwap = true;
		this.clear = false;
		this.renderToScreen = false;
	}

	render(renderer, writeBuffer, readBuffer) {
		this.uniforms.tDiffuse.value = readBuffer.texture;

		if (this.renderToScreen) {
			renderer.setRenderTarget(null);
		} else {
			renderer.setRenderTarget(writeBuffer);
			if (this.clear) renderer.clear();
		}

		this.fsQuad.render(renderer);
	}

	setSize(width, height) {
		this.resolution.set(width, height);
		this.uniforms.resolution.value.set(
			width, height, 1 / width, 1 / height
		);
	}

	dispose() {
		this.material.dispose();
		this.fsQuad.dispose();
	}
}
// ✅ AUTOMATIC GUI GENERATOR FOR POST-PROCESSING
class ControllerGUI {
	// Static properties to track all instances
	static instances = [];
	static sharedGui = null; // Single shared GUI instance
	static defaultFolderHeight = 150; // Estimated height per folder
	static defaultGap = 10; // Reduced gap between folders

	constructor(options = {}) {
		this.gui = null;
		this.folders = new Map();
		this.controllers = new Map();
		this.title = 'Controls(Tweak Only)';
		this.tooltip = 'These controls are for tweaking and fine-tuning only. Values are not final and will reset.';
		this.options = {
			useSharedGui: true, // Use single shared GUI instance
			title: this.title,
			tooltip: this.tooltip,
			position: 'top-right', // 'top-right', 'top-left', 'bottom-right', 'bottom-left'
			...options
		};
		this.logger = options.logger || console;
		// Add this instance to the static tracker
		ControllerGUI.instances.push(this);
	}

	// Initialize the main GUI (call this once)
	initGUI() {
		if (this.options.useSharedGui) {
			// Use shared GUI instance
			if (!ControllerGUI.sharedGui) {
				ControllerGUI.sharedGui = new lil.GUI();
				ControllerGUI.sharedGui.title(this.options.title);
				// Add tooltip to the main GUI title
				ControllerGUI.sharedGui.domElement.querySelector('.title').title = this.options.tooltip;
				this._positionGui(ControllerGUI.sharedGui);
			}
			this.gui = ControllerGUI.sharedGui;
		} else {
			// Create individual GUI instance
			if (!this.gui) {
				this.gui = new lil.GUI();
				this.gui.title(this.options.title);
				this.gui.domElement.querySelector('.title').title = this.options.tooltip;

				this._autoPosition();
			}
		}
		return this.gui;
	}

	// Position a GUI element
	_positionGui(gui, offset = 0) {
		const guiElement = gui.domElement;
		const { position } = this.options;

		// Remove default positioning
		guiElement.style.position = 'fixed';
		guiElement.style.top = 'auto';
		guiElement.style.right = 'auto';
		guiElement.style.bottom = 'auto';
		guiElement.style.left = 'auto';

		// Apply positioning based on corner
		switch (position) {
			case 'top-left':
				guiElement.style.top = `${15 + offset}px`;
				guiElement.style.left = '15px';
				break;
			case 'top-right':
				guiElement.style.top = `${15 + offset}px`;
				guiElement.style.right = '15px';
				break;
			case 'bottom-left':
				guiElement.style.bottom = `${15 + offset}px`;
				guiElement.style.left = '15px';
				break;
			case 'bottom-right':
				guiElement.style.bottom = `${15 + offset}px`;
				guiElement.style.right = '15px';
				break;
		}
	}

	// Automatically position this GUI based on existing instances (for individual GUIs)
	_autoPosition() {
		if (!this.gui) return;

		// Count how many GUIs are already positioned in the same position
		const samePositionGuis = ControllerGUI.instances.filter(instance =>
			instance !== this &&
			instance.gui &&
			!instance.options.useSharedGui &&
			instance.options.position === this.options.position
		);

		const index = samePositionGuis.length;
		const offset = index * (ControllerGUI.defaultFolderHeight + ControllerGUI.defaultGap);

		this._positionGui(this.gui, offset);
	}

	// Static method to update positioning of all instances
	static repositionAll() {
		ControllerGUI.instances.forEach(instance => {
			if (instance.gui && !instance.options.useSharedGui) {
				instance._autoPosition();
			}
		});
	}

	createAutoGUI(label, targetObject, config = {}) {
		if (!this.gui) this.initGUI();

		const flatConfig = this._flattenConfig(config);
		const folder = this.gui.addFolder(label);
		this.folders.set(label, folder);

		Object.keys(flatConfig).forEach(path => {
			const propConfig = flatConfig[path];
			const { object, key, value } = this._resolvePath(targetObject, path);

			if (value === undefined) {
				this.logger.warn(`Property '${path}' not found`);
				return;
			}

			// Display label from config OR fallback to key name
			const displayKey = propConfig.label || path.split('.').slice(-2, -1)[0] || path;

			let guiController;

			// Check if the config defines this as a vector (has x, y properties)
			const isVectorConfig = typeof propConfig === 'object' &&
				propConfig.hasOwnProperty('x') &&
				propConfig.hasOwnProperty('y');

			if (isVectorConfig || value?.isVector2 || value?.isVector3 ||
				(typeof value === 'object' && value !== null && value.hasOwnProperty('x') && value.hasOwnProperty('y'))) {

				// Handle Vector2/Vector3 or vector-like objects
				const axes = ['x', 'y', ...(value.hasOwnProperty('z') || propConfig.hasOwnProperty('z') ? ['z'] : [])];

				// Create a horizontal container for vector components
				const vectorContainer = document.createElement('div');
				vectorContainer.style.display = 'flex';
				vectorContainer.style.gap = '5px';
				vectorContainer.style.alignItems = 'center';
				vectorContainer.style.padding = '4px 8px';
				vectorContainer.style.backgroundColor = '#383838';
				vectorContainer.style.borderRadius = '3px';
				vectorContainer.style.margin = '2px 0';
				vectorContainer.style.fontSize = '11px';

				// Add vector label
				const vectorLabel = document.createElement('span');
				vectorLabel.textContent = displayKey + ':';
				vectorLabel.style.fontSize = '11px';
				vectorLabel.style.color = '#ccc';
				vectorLabel.style.minWidth = '50px';
				vectorLabel.style.fontWeight = '500';
				vectorContainer.appendChild(vectorLabel);

				axes.forEach(axis => {
					// Get axis-specific config if available
					const axisCfg = (typeof propConfig === 'object' && propConfig[axis]) ?
						propConfig[axis] :
						(typeof propConfig === 'object' ? propConfig : {});

					// Create axis container
					const axisDiv = document.createElement('div');
					axisDiv.style.display = 'flex';
					axisDiv.style.alignItems = 'center';
					axisDiv.style.gap = '2px';

					// Axis label
					const axisLabel = document.createElement('span');
					axisLabel.textContent = axis;
					axisLabel.style.fontSize = '9px';
					axisLabel.style.color = '#999';
					axisLabel.style.minWidth = '8px';
					axisLabel.style.textTransform = 'uppercase';
					axisLabel.style.fontWeight = 'bold';

					// Axis input
					const rawAxisValue = value[axis] !== undefined ? value[axis] : (propConfig[axis] || 0);
					const multiplier = axisCfg.multiplier ?? propConfig.multiplier ?? 1;

					const input = document.createElement('input');
					input.type = 'number';
					input.value = (rawAxisValue / multiplier).toFixed(2);
					input.step = axisCfg.step ?? 0.01;
					input.min = axisCfg.min ?? -10;
					input.max = axisCfg.max ?? 10;
					// style setup...
					input.style.width = '45px';
					input.style.fontSize = '10px';
					input.style.padding = '2px 4px';
					input.style.border = '1px solid #555';
					input.style.backgroundColor = '#2a2a2a';
					input.style.color = '#fff';
					input.style.borderRadius = '2px';
					input.style.textAlign = 'center';

					// hover & focus events
					input.addEventListener('mouseenter', () => input.style.borderColor = '#777');
					input.addEventListener('mouseleave', () => input.style.borderColor = '#555');
					input.addEventListener('focus', () => {
						input.style.borderColor = '#999';
						input.style.backgroundColor = '#333';
					});
					input.addEventListener('blur', () => {
						input.style.borderColor = '#555';
						input.style.backgroundColor = '#2a2a2a';
					});

					// input change handler
					input.addEventListener('input', (e) => {
						const newValue = parseFloat(e.target.value);
						if (!isNaN(newValue)) {
							const scaled = newValue * multiplier;
							if (value && typeof value === 'object') {
								value[axis] = scaled;
							} else {
								if (!object[key]) object[key] = {};
								object[key][axis] = scaled;
							}
							if (axisCfg.onChange) axisCfg.onChange(value || object[key]);
						}
					});


					axisDiv.appendChild(axisLabel);
					axisDiv.appendChild(input);
					vectorContainer.appendChild(axisDiv);
				});

				// Add to folder
				const folderElement = folder.domElement.querySelector('.children');
				folderElement.appendChild(vectorContainer);

			} else if (typeof value === 'number') {
				const scaledDisplayValue = propConfig.multiplier ? value / propConfig.multiplier : value;
				const controllerObject = { [displayKey]: scaledDisplayValue };

				guiController = folder.add(controllerObject, displayKey, propConfig.min, propConfig.max, propConfig.step)
					.onChange(v => {
						const scaled = propConfig.multiplier ? v * propConfig.multiplier : v;
						object[key] = scaled;
						if (propConfig.onChange) propConfig.onChange(scaled);
						guiController.domElement.title = `Actual: ${scaled}`;
					});
			} else if (typeof value === 'boolean') {
				const controllerObject = { [displayKey]: value };
				guiController = folder.add(controllerObject, displayKey)
					.onChange(v => {
						object[key] = v;
						if (propConfig.onChange) propConfig.onChange(v);
					});
			} else if (value?.isColor) {
				const colorObj = { [displayKey]: '#' + value.getHexString() };
				guiController = folder.addColor(colorObj, displayKey)
					.onChange(hex => {
						value.setHex(hex.replace('#', '0x'));
						object[key] = value;
						if (propConfig.onChange) propConfig.onChange(value);
					});
			} else if (typeof value === 'string' && value.startsWith('#')) {
				// Handle hex color strings
				const colorObj = { [displayKey]: value };
				guiController = folder.addColor(colorObj, displayKey)
					.onChange(hex => {
						object[key] = hex;
						if (propConfig.onChange) propConfig.onChange(hex);
					});
			}

			if (guiController) {
				const fullKey = `${label}.${path}`;
				this.controllers.set(fullKey, guiController);
			}
		});

		folder.close();
		return folder;
	}

	// Utility to resolve nested object path like "uniforms.intensity.value"
	_resolvePath(root, path) {
		const keys = path.split('.');
		let obj = root;
		for (let i = 0; i < keys.length - 1; i++) {
			obj = obj?.[keys[i]];
		}
		const key = keys[keys.length - 1];
		return { object: obj, key, value: obj?.[key] };
	}

	// Utility to flatten nested config object
	_flattenConfig(obj, parentKey = '', result = {}) {
		for (const key in obj) {
			const fullKey = parentKey ? `${parentKey}.${key}` : key;

			// Check if this is a vector-like object (has x, y properties)
			const isVectorConfig = typeof obj[key] === 'object' &&
				!Array.isArray(obj[key]) &&
				obj[key].hasOwnProperty('x') &&
				obj[key].hasOwnProperty('y') &&
				!('min' in obj[key]) &&
				!('max' in obj[key]);

			if (isVectorConfig) {
				// Treat as a vector object, don't flatten further
				result[fullKey] = obj[key];
			} else if (
				typeof obj[key] === 'object' &&
				!Array.isArray(obj[key]) &&
				!('min' in obj[key]) &&
				!('max' in obj[key])
			) {
				this._flattenConfig(obj[key], fullKey, result);
			} else {
				result[fullKey] = obj[key];
			}
		}
		return result;
	}

	// Destroy GUI and remove from instances tracker
	destroy() {
		// Only destroy individual GUI instances, not the shared one
		if (this.gui && !this.options.useSharedGui) {
			this.gui.destroy();
			this.gui = null;
		} else if (this.options.useSharedGui) {
			// For shared GUI, just remove folders belonging to this instance
			this.folders.forEach(folder => {
				if (folder.parent) {
					folder.parent.removeFolder(folder);
				}
			});
			this.gui = null;
		}

		this.folders.clear();
		this.controllers.clear();

		// Remove this instance from the tracker
		const index = ControllerGUI.instances.indexOf(this);
		if (index > -1) {
			ControllerGUI.instances.splice(index, 1);
		}

		// Reposition remaining individual GUIs
		ControllerGUI.repositionAll();
	}

	// Static method to destroy all GUIs
	static destroyAll() {
		// Destroy shared GUI if it exists
		if (ControllerGUI.sharedGui) {
			ControllerGUI.sharedGui.destroy();
			ControllerGUI.sharedGui = null;
		}

		// Create a copy of the array since destroy() modifies the original
		const instances = [...ControllerGUI.instances];
		instances.forEach(instance => instance.destroy());
	}
}
// ParticleSystemRegistry.js

class ParticleSystemRegistry {
	static #registry = new Map(); // private field

	/**
	 * Registers a ParticleSystem instance.
	 * @param {string|number} id
	 * @param {object} system
	 */
	static register(id, system) {
		this.#registry.set(id, system);
	}

	/**
	 * Retrieves a ParticleSystem instance.
	 * @param {string|number} id
	 * @returns {object|undefined}
	 */
	static get(id) {
		return this.#registry.get(id);
	}

	/**
	 * Removes a ParticleSystem by ID.
	 * @param {string|number} id
	 */
	static remove(id) {
		this.#registry.delete(id);
	}

	/**
	 * Clears all ParticleSystems.
	 */
	static clear() {
		this.#registry.clear();
	}

	/**
	 * Optional: returns all as array
	 */
	static getAll() {
		return Array.from(this.#registry.values());
	}
}
class Logger {
	constructor(enabled = false, prefix = "MyPlugin") {
		this.enabled = enabled;
		this.prefix = prefix;
	}

	_print(label, style, ...args) {
		if (!this.enabled) return;
		console.log(
			`%c${label}%c`,
			style,
			"color: inherit;",
			...args
		);
	}

	info(...args) {
		this._print(
			`[${this.prefix} INFO]`,
			"color: #2196F3; border: 1px solid #2196F3; padding: 1px 4px; border-radius: 6px; font-weight: bold; font-size: 11px;",
			...args
		);
	}

	debug(...args) {
		this._print(
			`[${this.prefix} DEBUG]`,
			"color: #9E9E9E; border: 1px solid #9E9E9E; padding: 1px 4px; border-radius: 6px; font-style: italic; font-size: 11px;",
			...args
		);
	}

	warn(...args) {
		this._print(
			`[${this.prefix} WARN]`,
			"color: #FFC107; border: 1px solid #FFC107; padding: 1px 4px; border-radius: 6px; font-weight: bold; font-size: 11px;",
			...args
		);
	}

	error(...args) {
		this._print(
			`[${this.prefix} ERROR]`,
			"color: #F44336; border: 1px solid #F44336; padding: 1px 4px; border-radius: 6px; font-weight: bold; font-size: 11px; background: rgba(244,67,54,0.1);",
			...args
		);
	}
}




